window.HOEREN_TESTS[85] = {"id":"beim-physiotherapeuten","name":"Beim Physiotherapeuten","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Physio-Praxis Aktiv. Ihr Termin für die Rückenbehandlung ist nächste Woche. Aber nicht am Montag, sondern am Mittwoch um 10 Uhr. Bitte bringen Sie bequeme Kleidung und ein Handtuch mit. Wenn Sie verhindert sind, sagen Sie bitte einen Tag vorher ab. Bis dann!","gender":"f","q":"Wann ist der Termin?","opts":["Am Mittwoch.","Am Montag.","Am Freitag."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Du, mein Rücken macht mir zu schaffen, vom vielen Sitzen im Büro. Der Arzt hat mir Physiotherapie verschrieben. Ich gehe jetzt zweimal die Woche. Du hast doch auch Rückenprobleme. Kennst du gute Übungen für zu Hause? Ruf zurück, wir können uns austauschen. Danke!","gender":"m","q":"Warum hat Markus Rückenprobleme?","opts":["Vom Sport.","Vom vielen Sitzen.","Von einem Unfall."],"correct":1},{"transcript":"Achtung Patienten: Unsere Praxis bietet ab Mai einen neuen Kurs an — Rückengymnastik in der Gruppe, jeden Dienstagabend. Es ist nicht Schwimmen und auch nicht Yoga, sondern Gymnastik für den Rücken. Acht Termine, die Krankenkasse zahlt einen Teil. Bitte melden Sie sich früh an, die Gruppe ist klein. Auch Massagen sind weiter buchbar. Wir freuen uns auf Sie!","gender":"m","q":"Was ist der neue Kurs?","opts":["Rückengymnastik in der Gruppe.","Schwimmen.","Yoga."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Nach meiner Knie-Operation gehe ich jetzt zur Physiotherapie und es hilft so sehr! Am Anfang konnte ich kaum laufen, jetzt geht es viel besser. Die Therapeutin ist super geduldig. Mach dir keine Sorgen wegen deiner Schulter, das wird auch wieder. Bis bald!","gender":"f","q":"Warum geht Anna zur Physiotherapie?","opts":["Wegen Kopfschmerzen.","Wegen einer Erkältung.","Nach einer Knie-Operation."],"correct":2},{"transcript":"Liebe Patienten: Bitte denken Sie daran, dass Sie eine Verordnung vom Arzt brauchen. Ohne dieses Rezept können wir die Behandlung nicht mit der Krankenkasse abrechnen. Eine Behandlung ohne Rezept ist möglich, aber Sie zahlen dann selbst. Bringen Sie das Rezept zum ersten Termin mit. Vielen Dank!","gender":"f","q":"Was braucht man für die Abrechnung mit der Kasse?","opts":["Nur die Versichertenkarte.","Eine Verordnung vom Arzt.","Bargeld."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer hat welches Problem? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Praxis ist heute voll. Wo tut es dir denn weh?"},{"speaker":"Lisa","gender":"f","text":"Es tut überall ein bisschen weh. Wir sagen dem Arzt alles der Reihe nach."},{"speaker":"Lukas","gender":"m","text":"Bei mir sind es die Rückenschmerzen. Ich kann seit gestern nicht lange sitzen."},{"speaker":"Lisa","gender":"f","text":"Das kommt vom vielen Sitzen. Hat jemand starke Kopfschmerzen?"},{"speaker":"Lukas","gender":"m","text":"Kopfschmerzen hat von uns keiner."},{"speaker":"Lisa","gender":"f","text":"Ich habe ein verletztes Knie vom Lauf im Park. Das tut beim Gehen weh."},{"speaker":"Lukas","gender":"m","text":"Dann geh die Treppe langsam. Tom trägt im Geschäft schwere Taschen."},{"speaker":"Lisa","gender":"f","text":"Tom hat Schulterschmerzen. Er kann den Arm nicht mehr nach oben nehmen."},{"speaker":"Lukas","gender":"m","text":"Der Arzt kennt das. Kommen bei jemandem Hüftschmerzen vom langen Laufen?"},{"speaker":"Lisa","gender":"f","text":"Hüftschmerzen hat auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara sitzt den ganzen Tag am Schreibtisch."},{"speaker":"Lisa","gender":"f","text":"Bei Sara ist ein steifer Nacken das Problem. Der Kopf geht nur noch wenig zur Seite."},{"speaker":"Lukas","gender":"m","text":"Sie soll oft eine Pause machen. Tim ist gestern auf der Treppe gefallen."},{"speaker":"Lisa","gender":"f","text":"Tim hat einen verstauchten Fuß. Er kann heute nicht gut gehen."},{"speaker":"Lukas","gender":"m","text":"Der Arzt hilft ihm heute."},{"speaker":"Lisa","gender":"f","text":"Ich hole uns Nummern an der Tür."}],"options":[{"letter":"a","text":"Handgelenk-Probleme"},{"letter":"b","text":"Hüftschmerzen"},{"letter":"c","text":"Verletztes Knie"},{"letter":"d","text":"Kopfschmerzen"},{"letter":"e","text":"Rückenschmerzen"},{"letter":"f","text":"Steifer Nacken"},{"letter":"g","text":"Verstauchter Fuß"},{"letter":"h","text":"Ellbogenschmerzen"},{"letter":"i","text":"Schulterschmerzen"}],"items":[{"person":"Lukas","correct":"e"},{"person":"Lisa","correct":"c"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"f"},{"person":"Tim","correct":"g"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Patient","gender":"m","text":"Guten Tag, wie viele Behandlungen brauche ich? Reichen drei, oder gleich zehn?"},{"speaker":"Therapeutin","gender":"f","text":"Erst mal sechs, dann sehen wir weiter. Drei ist oft zu wenig, zehn brauchen wir nicht sofort."},{"speaker":"Patient","gender":"m","text":"Und wenn es nicht besser wird? Dann zehn, oder bleiben wir bei sechs?"},{"speaker":"Therapeutin","gender":"f","text":"Dann verschreibt der Arzt mehr. Zuerst sechs, nicht drei und nicht gleich zehn."},{"speaker":"Patient","gender":"m","text":"Gut, dann starten wir mit sechs Terminen. Danke."}],"q":"Wie viele Behandlungen sind zuerst geplant?","opts":["Drei.","Zehn.","Sechs."],"correct":2},{"lines":[{"speaker":"Therapeut","gender":"m","text":"Machen Sie die Übungen auch zu Hause? Oder schlafen Sie nur mehr, oder nehmen Sie Tabletten?"},{"speaker":"Patientin","gender":"f","text":"Ehrlich gesagt, selten. Ich schlafe viel und nehme manchmal Tabletten, aber üben tue ich wenig."},{"speaker":"Therapeut","gender":"m","text":"Das Üben zu Hause ist wichtig, sonst hilft es wenig. Mehr schlafen und Tabletten ersetzen die Übungen nicht."},{"speaker":"Patientin","gender":"f","text":"Okay, ich übe ab jetzt täglich zu Hause, nicht nur schlafen und keine extra Tabletten."}],"q":"Was soll die Patientin tun?","opts":["Mehr schlafen.","Täglich zu Hause üben.","Tabletten nehmen."],"correct":1},{"lines":[{"speaker":"Patientin","gender":"f","text":"Darf ich weiter Sport machen? Schwimmen, joggen, radfahren?"},{"speaker":"Therapeutin","gender":"f","text":"Schwimmen ja, Joggen lieber nicht. Joggen ist jetzt zu hart für Ihr Knie."},{"speaker":"Patientin","gender":"f","text":"Und Radfahren? Ist das wie Joggen, oder eher wie Schwimmen?"},{"speaker":"Therapeutin","gender":"f","text":"Radfahren ist gut für Ihr Knie, wie Schwimmen. Nur Joggen sollen Sie nicht machen."},{"speaker":"Patientin","gender":"f","text":"Verstanden, schwimmen und radfahren ja, joggen nein. Danke."}],"q":"Welchen Sport soll die Patientin nicht machen?","opts":["Schwimmen.","Radfahren.","Joggen."],"correct":2},{"lines":[{"speaker":"Patient","gender":"m","text":"Die Massage hat sehr gutgetan. Soll ich mich jetzt hinlegen oder sofort Sport machen?"},{"speaker":"Therapeut","gender":"m","text":"Schön, ist der Nacken lockerer? Legen Sie sich nicht den ganzen Tag hin, und machen Sie heute keinen Sport."},{"speaker":"Patient","gender":"m","text":"Ja, viel besser. Was soll ich dann tun?"},{"speaker":"Therapeut","gender":"m","text":"Trinken Sie heute viel Wasser. Nicht hinlegen den ganzen Tag und nicht sofort Sport, sondern viel trinken."},{"speaker":"Patient","gender":"m","text":"Gut, dann trinke ich viel Wasser. Danke."}],"q":"Was soll der Patient nach der Massage tun?","opts":["Viel Wasser trinken.","Sich hinlegen.","Sofort Sport machen."],"correct":0},{"lines":[{"speaker":"Patientin","gender":"f","text":"Ich muss meinen Termin verschieben. Dienstag geht nicht, Freitag auch nicht so gut."},{"speaker":"Empfang","gender":"f","text":"Kein Problem, auf wann? Dienstag ist voll, Freitag haben wir noch einen Platz am Nachmittag."},{"speaker":"Patientin","gender":"f","text":"Geht Donnerstag statt Dienstag? Freitag ist bei mir zu spät."},{"speaker":"Empfang","gender":"f","text":"Ja, Donnerstag um 11 Uhr. Nicht Dienstag und nicht Freitag, Donnerstag passt."},{"speaker":"Patientin","gender":"f","text":"Perfekt, dann Donnerstag um 11. Danke."}],"q":"Auf welchen Tag verschiebt sie den Termin?","opts":["Dienstag.","Donnerstag.","Freitag."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Krämer, einem Physiotherapeuten. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Krämer, mit welchem Problem kommen die Leute am häufigsten?"},{"speaker":"Krämer","gender":"m","text":"Mit dem Rücken. Die meisten Patienten kommen mit Rückenproblemen. Wir sitzen einfach zu viel, im Büro und im Auto."},{"speaker":"Reporterin","gender":"f","text":"Wie wichtig ist die Mithilfe der Patienten zu Hause?"},{"speaker":"Krämer","gender":"m","text":"Sehr wichtig, sie müssen die Übungen auch zu Hause machen. Ohne Üben zu Hause hilft die Stunde hier wenig. Die Übungen sind also wichtig, nicht unwichtig."},{"speaker":"Reporterin","gender":"f","text":"Kann man Rückenschmerzen vermeiden, oder kommt das immer?"},{"speaker":"Krämer","gender":"m","text":"Ja, man kann sie vermeiden. Stehen Sie öfter auf, bewegen Sie sich und machen Sie Sport. Schwimmen ist gut, auch Spazierengehen hilft."},{"speaker":"Reporterin","gender":"f","text":"Sind die Geräte besser als Ihre Hände?"},{"speaker":"Krämer","gender":"m","text":"Nein, meine Hände bleiben das wichtigste Werkzeug. Die Geräte sind nicht besser als die Hände. Ich spüre mit den Händen, wo das Problem ist."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie den Menschen im Alltag?"},{"speaker":"Krämer","gender":"m","text":"Bleiben Sie aktiv. Haben Sie keine Angst vor Bewegung. Ein kurzer Spaziergang am Abend ist schon ein guter Start, jeden Tag. Auch zehn Minuten reichen am Anfang, Hauptsache regelmäßig. So bleibt der Rücken lange fit und stark genug."}],"items":[{"q":"Herr Krämer findet, die Übungen zu Hause sind nicht wichtig.","correct":"nein"},{"q":"Die meisten Patienten kommen mit Rückenproblemen.","correct":"ja"},{"q":"Er sagt, man kann Rückenschmerzen vermeiden.","correct":"ja"},{"q":"Für ihn sind die Geräte besser als seine Hände.","correct":"nein"},{"q":"Er rät, aktiv zu bleiben.","correct":"ja"}]}]};
